import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Set up ripeat with your AI assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai-setup.md","filePath":"ai-setup.md"}'),o={name:"ai-setup.md"};function i(r,t,p,l,c,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="set-up-ripeat-with-your-ai-assistant" tabindex="-1">Set up ripeat with your AI assistant <a class="header-anchor" href="#set-up-ripeat-with-your-ai-assistant" aria-label="Permalink to &quot;Set up ripeat with your AI assistant&quot;">​</a></h1><p>Paste the text below into your AI assistant (Claude Code, Codex, or another that can run commands on your computer). It installs ripeat and connects the assistant to it. Nothing happens without your yes at each step, and the assistant gets no power to install software for you.</p><h2 id="the-prompt" tabindex="-1">The prompt <a class="header-anchor" href="#the-prompt" aria-label="Permalink to &quot;The prompt&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install ripeat on this computer and connect it to you, step by step. ripeat is a tool that sets up a machine from a list and can undo it; its website is https://ripeat.github.io.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rules you must follow:</span></span>
<span class="line"><span>- Before each command, say what it does and wait for me to agree. Never add --yes, --accept-risk or --allow-admin, and never pipe a download into a shell.</span></span>
<span class="line"><span>- Install ripeat only with Homebrew (macOS or Linux: brew install ripeat/tap/ripeat) or with Scoop (Windows: scoop install git; scoop bucket add ripeat https://github.com/ripeat/scoop-bucket; scoop install ripeat). If neither is installed, stop and tell me; do not install them for me.</span></span>
<span class="line"><span>- Check it with: ripeat version</span></span>
<span class="line"><span>- Then connect yourself with ripeat&#39;s own setup command, for the assistant you are: ripeat mcp setup --client claude-code, or claude-desktop, or codex. Show me what it will change and let it ask me. Do not use --allow-run.</span></span>
<span class="line"><span>- Then stop. Do not use ripeat to install any of my tools. That is a separate request, and I will ask for it. Tell me to restart you (or the app) so the connection is picked up.</span></span></code></pre></div><h2 id="what-it-can-and-cannot-do" tabindex="-1">What it can and cannot do <a class="header-anchor" href="#what-it-can-and-cannot-do" aria-label="Permalink to &quot;What it can and cannot do&quot;">​</a></h2><ul><li><strong>It can</strong> install ripeat through Homebrew or Scoop, check the version, and register ripeat&#39;s MCP server with your assistant using <a href="./mcp#connecting"><code>ripeat mcp setup</code></a>, which shows the change, keeps a backup of any file it edits and asks first.</li><li><strong>It cannot</strong> install your tools (the prompt tells the assistant not to, and without <code>--allow-run</code> ripeat&#39;s server offers no install tool at all), accept a risk for you, or add <code>--yes</code>.</li><li>The prompt lives on this site over HTTPS, so what you paste is what is published here. An assistant is an instruction follower, not a lock: the real protections are ripeat&#39;s own confirmations and the <a href="./admin-policy">administrator policy</a>, not the wording of the prompt.</li></ul><p>An assistant that only has a shell can also use <a href="./agent-skill">the skill</a>.</p><p>After the restart, ask the assistant something like &quot;Set up git, node and ripgrep on this machine.&quot; It looks each one up, builds the plan and its risk rating, and gives you the <code>ripeat install</code> command to read and run yourself. To let it run the install after you confirm each run in its own app, see <a href="./mcp#letting-the-assistant-install-ripeat-mcp---allow-run-off-by-default">ripeat as an MCP server</a>.</p>`,8)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
